module army_movement (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] n,\n    input wire [7:0] edge_u [0:6],\n    input wire [7:0] edge_v [0:6],\n    input wire [7:0] edge_cost [0:6],\n    input wire [7:0] x [0:7],\n    input wire [7:0] y [0:7],\n    output reg [23:0] total_cost,\n    output reg done\n);\n\n    // Maximum parameters\n    parameter MAX_N = 8;\n    parameter MAX_EDGES = 7;\n\n    // Internal registers\n    reg [7:0] parent [0:MAX_N-1];\n    reg [7:0] cost_to_parent [0:MAX_N-1];\n    reg [7:0] children [0:MAX_N-1][0:MAX_N-1];\n    reg [7:0] child_count [0:MAX_N-1];\n    reg signed [7:0] net_flow [0:MAX_N-1];\n    reg [7:0] child_index [0:MAX_N-1];\n    reg [2:0] stack [0:MAX_N-1];\n    reg [2:0] stack_top;\n    reg [2:0] queue [0:MAX_N-1];\n    reg [2:0] q_head;\n    reg [2:0] q_tail;\n    reg [7:0] i, j, u, v, child;\n    reg [15:0] temp_cost;\n    reg signed [7:0] temp_flow;\n    reg [2:0] accum_child;\n    reg [7:0] current_node;\n    \n    // State machine states\n    reg [2:0] state;\n    localparam [2:0] IDLE       = 3'd0;\n    localparam [2:0] BUILD_TREE = 3'd1;\n    localparam [2:0] DFS        = 3'd2;\n    localparam [2:0] ACCUMULATE = 3'd3;\n    localparam [2:0] DONE       = 3'd4;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset\n            done <= 1'b0;\n            total_cost <= 24'd0;\n            state <= IDLE;\n            stack_top <= 3'd0;\n            q_head <= 3'd0;\n            q_tail <= 3'd0;\n            for (i = 3'd0; i < MAX_N; i = i + 3'd1) begin\n                parent[i] <= 8'hFF;\n                child_count[i] <= 8'd0;\n                net_flow[i] <= 8'd0;\n                child_index[i] <= 8'd0;\n                cost_to_parent[i] <= 8'd0;\n                for (j = 3'd0; j < MAX_N; j = j + 3'd1) begin\n                    children[i][j] <= 8'hFF;\n                end\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    total_cost <= 24'd0;\n                    if (start) begin\n                        // Initialize BFS\n                        for (i = 3'd0; i < MAX_N; i = i + 3'd1) begin\n                            parent[i] <= 8'hFF;\n                            child_count[i] <= 8'd0;\n                            cost_to_parent[i] <= 8'd0;\n                            net_flow[i] <= 8'd0;\n                            child_index[i] <= 8'd0;\n                            for (j = 3'd0; j < MAX_N; j = j + 3'd1) begin\n                                children[i][j] <= 8'hFF;\n                            end\n                        end\n                        parent[8'd0] <= 8'hFF;  // Mark root as unvisited initially\n                        queue[3'd0] <= 3'd0;\n                        q_head <= 3'd0;\n                        q_tail <= 3'd1;\n                        state <= BUILD_TREE;\n                    end\n                end\n\n                BUILD_TREE: begin\n                    if (q_head != q_tail) begin\n                        // Dequeue node\n                        u <= queue[q_head];\n                        q_head <= q_head + 3'd1;\n                        i <= 8'd0;\n                    end else begin\n                        // Tree built, initialize DFS\n                        stack_top <= 3'd0;\n                        stack[stack_top] <= 3'd0;\n                        stack_top <= stack_top + 3'd1;\n                        for (i = 3'd0; i < MAX_N; i = i + 3'd1) begin\n                            net_flow[i] <= 8'd0;\n                        end\n                        total_cost <= 24'd0;\n                        state <= DFS;\n                    end\n                end\n\n                DFS: begin\n                    if (stack_top != 3'd0) begin\n                        // Get current node from stack\n                        u <= stack[stack_top - 3'd1];\n                        if (child_index[stack[stack_top - 3'd1]] < child_count[stack[stack_top - 3'd1]]) begin\n                            // Push next child to stack\n                            child <= children[u][child_index[u]];\n                            child_index[u] <= child_index[u] + 8'd1;\n                            stack[stack_top] <= children[u][child_index[u]];\n                            stack_top <= stack_top + 3'd1;\n                        end else begin\n                            // All children processed, now accumulate\n                            current_node <= u;\n                            accum_child <= 3'd0;\n                            net_flow[u] <= $signed(x[u]) - $signed(y[u]);\n                            state <= ACCUMULATE;\n                        end\n                    end else begin\n                        state <= DONE;\n                        done <= 1'b1;\n                    end\n                end\n\n                ACCUMULATE: begin\n                    if (accum_child < child_count[current_node]) begin\n                        // Add child's net flow and cost\n                        child <= children[current_node][accum_child];\n                        net_flow[current_node] <= net_flow[current_node] + net_flow[children[current_node][accum_child]];\n                        // Calculate absolute value\n                        if (net_flow[child][7]) begin\n                            temp_flow <= -net_flow[child];\n                        end else begin\n                            temp_flow <= net_flow[child];\n                        end\n                        // Add cost: |net_flow| * cost_to_parent\n                        total_cost <= total_cost + (temp_flow * cost_to_parent[child]);\n                        accum_child <= accum_child + 3'd1;\n                    end else begin\n                        // Pop node from stack\n                        stack_top <= stack_top - 3'd1;\n                        state <= DFS;\n                    end\n                end\n\n                DONE: begin\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= IDLE;\n                        done <= 1'b0;\n                    end\n                end\n                default: state <= IDLE;\n            endcase\n\n            // Edge processing during BUILD_TREE\n            if (state == BUILD_TREE && q_head != q_tail && i < MAX_EDGES) begin\n                if (edge_u[i] == u && parent[edge_v[i]] == 8'hFF && edge_v[i] < n) begin\n                    v <= edge_v[i];\n                    parent[edge_v[i]] <= u;\n                    cost_to_parent[edge_v[i]] <= edge_cost[i];\n                    children[u][child_count[u]] <= edge_v[i];\n                    child_count[u] <= child_count[u] + 8'd1;\n                    queue[q_tail] <= edge_v[i];\n                    q_tail <= q_tail + 3'd1;\n                    i <= i + 8'd1;\n                end else if (edge_v[i] == u && parent[edge_u[i]] == 8'hFF && edge_u[i] < n) begin\n                    v <= edge_u[i];\n                    parent[edge_u[i]] <= u;\n                    cost_to_parent[edge_u[i]] <= edge_cost[i];\n                    children[u][child_count[u]] <= edge_u[i];\n                    child_count[u] <= child_count[u] + 8'd1;\n                    queue[q_tail] <= edge_u[i];\n                    q_tail <= q_tail + 3'd1;\n                    i <= i + 8'd1;\n                end else begin\n                    i <= i + 8'd1;\n                end\n            end\n        end\n    end\n\nendmodule